<template>
 <main class="hub">
  <header class="hub-header"><div><router-link to="/projects" class="back">← Projects & Tasks</router-link><p class="eyebrow">DELIVERY WORKSPACE / PROJECT</p><h1>{{project?.name||'Project workspace'}}</h1><p>{{project?.description||'Plan work, delivery and effort in one place.'}}</p></div><span v-if="project" class="project-pill">{{project.status}} · {{project.health}}</span></header>
  <p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p><p v-if="loading" role="status">Loading project workspace…</p>
  <template v-else-if="project">
   <section class="insights"><article><small>Delivery method</small><strong>{{project.deliveryMethod==='WATERFALL'?'Waterfall':'Kanban / Agile'}}</strong></article><article><small>Work items</small><strong>{{tasks.length}}</strong></article><article><small>Completed</small><strong>{{progress}}%</strong></article><article><small>Approved time</small><strong>{{hours.toFixed(1)}} h</strong></article></section>
   <nav class="hub-tabs" aria-label="Project workspace views"><button v-for="item in tabs" :key="item.key" type="button" :class="{active:view===item.key}" @click="view=item.key">{{item.label}}</button></nav>
   <section v-if="view==='info'" class="panel">
    <div class="section-title"><h2>Project information</h2><span>Approved project charter</span></div>
    <div class="information"><div><small>Project name</small><strong>{{project.name}}</strong></div><div><small>Client / business unit</small><strong>{{project.client||'Not specified'}}</strong></div><div><small>Status</small><strong>{{project.status}}</strong></div><div><small>Health</small><strong>{{project.health}}</strong></div><div><small>Planned start</small><strong>{{date(project.startDate)}}</strong></div><div><small>Target completion</small><strong>{{date(project.targetEndDate)}}</strong></div><div><small>Delivery approach</small><strong>{{project.deliveryMethod||'KANBAN'}}</strong></div></div>
    <div class="overview"><h3>Overview</h3><p>{{project.description||'No project overview has been provided.'}}</p></div><router-link :to="'/projects/detail?projectId='+encodeURIComponent(project.id)" class="secondary-link">Submit project amendments for approval</router-link>
   </section>
   <section v-if="view==='timesheets'" class="panel"><div class="section-title"><h2>Project timesheet</h2><router-link to="/timesheets" class="secondary-link">Submit time entry</router-link></div><p class="hint">These entries show approved effort only. Team access follows the project's existing timesheet permissions.</p>
    <div class="scroll-table"><table><thead><tr><th>Date</th><th>Team member</th><th>Hours</th><th>Work description</th></tr></thead><tbody><tr v-for="row in entries" :key="row.id"><td>{{date(row.workDate)}}</td><td>{{row.userName||'Team member'}}</td><td>{{Number(row.hours).toFixed(2)}}</td><td>{{row.description||'—'}}</td></tr><tr v-if="!entries.length"><td colspan="4">No approved time entries yet.</td></tr></tbody></table></div>
   </section>
   <section v-if="view==='timeline'" class="panel"><div class="section-title"><h2>Project timeline</h2><div class="timeline-controls"><label for="timeline-scale">Scale</label><SmartSelect id="timeline-scale" v-model="timelineScale" aria-label="Timeline scale" :options="[{value:'month',label:'Month'},{value:'quarter',label:'Quarter'},{value:'year',label:'Year'}]" /><span>{{tasks.length}} work items</span></div></div><p class="hint">Milestones, project dates and task dependencies share one schedule. Select a bar to inspect a work item.</p>
    <div v-if="!datedItems.length" class="empty">No scheduled work yet. Add project dates or plan work-item dates to see the timeline.</div>
    <div v-else class="timeline-scroll"><div class="timeline-head"><span>Work item</span><span>{{date(new Date(timelineMin).toISOString())}}</span><span>{{date(new Date(timelineMax).toISOString())}}</span></div><div v-for="item in datedItems" :key="item.id" class="timeline-row"><strong>{{item.title}}</strong><div class="timeline-track"><button type="button" class="timeline-bar" :class="[item.status.toLowerCase(),{'milestone':item.itemType==='MILESTONE'}]" :style="barStyle(item)" :title="item.title+' · '+date(item.startDate||item.dueDate)+' → '+date(item.dueDate||item.startDate)" :disabled="item.id==='project-charter'" @click="openDetails(item)"><span class="sr-only">Inspect {{item.title}}</span></button></div><small>{{item.phase||item.itemType}}</small></div></div>
   </section>
   <section v-if="view==='backlog'||view==='kanban'||view==='waterfall'" class="panel">
    <div class="section-title"><div><h2>{{view==='backlog'?'Work item backlog':view==='kanban'?'Kanban board':'Waterfall delivery phases'}}</h2><p class="hint">Epics, stories, tasks, bugs and milestones use one approved work-item register.</p></div><button type="button" class="primary" @click="showCreate=!showCreate">{{showCreate?'Close creation':'+ New work item'}}</button></div>
    <PremiumComposeDialog :open="showCreate" title="Create a work item" eyebrow="PROJECTS / NEW WORK" description="Describe the outcome, set delivery details, and submit it for independent approval." :error="error" @close="showCreate=false">
    <form class="item-form" @submit.prevent="createItem"><div class="field-grid"><label>Work type <SmartSelect v-model="draft.itemType" aria-label="Work item type" :options="types.map(x=>({value:x,label:x}))"/></label><label>Priority <SmartSelect v-model="draft.priority" aria-label="Work priority" :options="priorities.map(x=>({value:x,label:x}))"/></label><label class="wide">Title <input v-model.trim="draft.title" required minlength="2" maxlength="200" placeholder="As a user, I want…" /></label><label class="wide">Description <textarea v-model.trim="draft.description" maxlength="1500" rows="3" placeholder="Requirements, acceptance criteria, context"/></label><label>Phase / stage <input v-model.trim="draft.phase" maxlength="100" placeholder="e.g. Design, Build, Test"/></label><label>Start date <SmartDatePicker v-model="draft.startDate" aria-label="Work start date" /></label><label>Due date <SmartDatePicker v-model="draft.dueDate" aria-label="Work due date" :min="draft.startDate" /></label><label>Parent story / epic <SmartSelect v-model="draft.parentId" aria-label="Parent work item" :options="[{value:'',label:'No parent'},...tasks.filter(t=>['EPIC','STORY','TASK'].includes(t.itemType)).map(t=>({value:t.id,label:t.title}))]" /></label><label>Depends on <SmartSelect v-model="draft.dependsOnId" aria-label="Dependency work item" :options="[{value:'',label:'No dependency'},...tasks.map(t=>({value:t.id,label:t.title}))]" /></label></div><button class="primary" :disabled="busy||draft.title.length<2" type="submit">{{busy?'Submitting…':'Submit work item for approval'}}</button></form>
    </PremiumComposeDialog>
    <div v-if="view==='backlog'" class="backlog"><article v-for="task in tasks" :key="task.id" class="work-row"><span class="type">{{task.itemType||'TASK'}}</span><div><button class="task-title" type="button" @click="openDetails(task)">{{task.title}}</button><small>{{task.phase||'Unassigned phase'}} · {{task.priority||'MEDIUM'}} priority · {{date(task.dueDate)}}</small></div><SmartSelect :model-value="task.status" :aria-label="'Status for '+task.title" :options="statuses.map(x=>({value:x,label:pretty(x)}))" :disabled="busy" @change="updateStatus(task,$event)" /></article><div v-if="!tasks.length" class="empty">No approved work items yet. Create an epic, story or task to start the backlog.</div></div>
    <div v-else-if="view==='kanban'" class="board"><div v-for="status in statuses" :key="status" class="board-column" @dragover.prevent @drop.prevent="dropTask(status)"><div class="column-head"><strong>{{pretty(status)}}</strong><span>{{tasks.filter(t=>t.status===status).length}}</span></div><article v-for="task in tasks.filter(t=>t.status===status)" :key="task.id" class="board-card" draggable="true" @dragstart="dragTask(task,$event)" @dragend="draggingId=''"><small>{{task.itemType||'TASK'}} · {{task.priority||'MEDIUM'}}</small><button class="task-title" type="button" @click="openDetails(task)">{{task.title}}</button><p>{{task.description||'No details yet'}}</p><small v-if="task.parentId">Subtask · {{taskName(task.parentId)}}</small><small v-if="task.dependsOnId">Depends on · {{taskName(task.dependsOnId)}}</small><SmartSelect :model-value="task.status" :disabled="busy" :aria-label="'Move '+task.title" :options="statuses.map(x=>({value:x,label:pretty(x)}))" @change="updateStatus(task,$event)" /></article></div></div>
    <div v-else class="phases"><div v-for="phase in phases" :key="phase" class="phase"><h3>{{phase}} <span>{{tasks.filter(t=>(t.phase||'Unassigned')===phase).length}} items</span></h3><article v-for="task in tasks.filter(t=>(t.phase||'Unassigned')===phase)" :key="task.id" class="work-row"><span class="type">{{task.itemType||'TASK'}}</span><div><button class="task-title" type="button" @click="openDetails(task)">{{task.title}}</button><small>{{date(task.startDate)}} → {{date(task.dueDate)}}</small></div><SmartSelect :model-value="task.status" :aria-label="'Status for '+task.title" :disabled="busy" :options="statuses.map(x=>({value:x,label:pretty(x)}))" @change="updateStatus(task,$event)"/></article></div><div v-if="!phases.length" class="empty">No phases yet. Add work items with a phase name.</div></div>
   </section>
   <div v-if="selectedTask" class="task-overlay" @click.self="selectedTask=null" @keydown.esc="selectedTask=null">
     <section class="task-dialog" role="dialog" aria-modal="true" aria-label="Work item details" tabindex="-1">
       <header class="task-dialog-head"><div><small>{{selectedTask.itemType||'TASK'}} · {{selectedTask.priority||'MEDIUM'}}</small><h2>{{selectedTask.title}}</h2></div><button type="button" class="icon-close" aria-label="Close work item details" @click="selectedTask=null">✕</button></header>
       <p v-if="error" role="alert" class="alert error">{{error}}</p><p v-if="notice" role="status" class="alert">{{notice}}</p>
       <div class="task-dialog-body">
        <label>Title<input v-model.trim="detail.title" maxlength="200" required /></label>
        <label>Description<textarea v-model.trim="detail.description" rows="4" maxlength="1500" /></label>
        <div class="field-grid">
          <label>Type<SmartSelect v-model="detail.itemType" aria-label="Detail work type" :options="types.map(t=>({value:t,label:t}))"/></label>
          <label>Priority<SmartSelect v-model="detail.priority" aria-label="Detail priority" :options="priorities.map(t=>({value:t,label:t}))"/></label>
          <label>Phase<input v-model.trim="detail.phase" maxlength="100" /></label>
          <label>Status<SmartSelect v-model="detail.status" aria-label="Detail status" :options="statuses.map(t=>({value:t,label:pretty(t)}))"/></label>
          <label>Start<SmartDatePicker v-model="detail.startDate" aria-label="Detail start date" /></label>
          <label>Due<SmartDatePicker v-model="detail.dueDate" aria-label="Detail due date" :min="detail.startDate" /></label>
          <label>Parent<SmartSelect v-model="detail.parentId" aria-label="Detail parent work item" :options="[{value:'',label:'No parent'},...tasks.filter(t=>t.id!==selectedTask.id&&['EPIC','STORY','TASK'].includes(t.itemType)).map(t=>({value:t.id,label:t.title}))]"/></label>
          <label>Depends on<SmartSelect v-model="detail.dependsOnId" aria-label="Detail dependency" :options="[{value:'',label:'No dependency'},...tasks.filter(t=>t.id!==selectedTask.id).map(t=>({value:t.id,label:t.title}))]"/></label>
        </div>
        <div v-if="subtasks.length" class="related-items"><strong>Subtasks</strong><button v-for="subtask in subtasks" :key="subtask.id" type="button" @click="openDetails(subtask)">{{subtask.title}} · {{pretty(subtask.status)}}</button></div>
        <p class="hint">Edits, dependency changes and status moves require independent approval before appearing on the board.</p>
       </div>
       <footer class="task-dialog-actions"><button type="button" class="secondary" @click="selectedTask=null">Cancel</button><button type="button" class="primary" :disabled="busy||detail.title.length<2" @click="saveDetails">{{busy?'Submitting…':'Submit changes for approval'}}</button></footer>
     </section>
   </div>
  </template>
 </main>
</template>
<script setup>
import {computed,onMounted,reactive,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import axios from '../../../api/axiosConfig';
import SmartSelect from '../../../components/SmartSelect.vue';
import SmartDatePicker from '../../../components/SmartDatePicker.vue';
import PremiumComposeDialog from '../../../components/PremiumComposeDialog.vue';
const route=useRoute(),project=ref(null),tasks=ref([]),entries=ref([]),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),showCreate=ref(false);
const types=['EPIC','STORY','TASK','BUG','MILESTONE'],priorities=['LOW','MEDIUM','HIGH','CRITICAL'],statuses=['TODO','IN_PROGRESS','BLOCKED','DONE'];
const tabs=[{key:'info',label:'Project info'},{key:'timesheets',label:'Timesheets'},{key:'timeline',label:'Timeline'},{key:'backlog',label:'Backlog'},{key:'kanban',label:'Kanban'},{key:'waterfall',label:'Waterfall'}];
const view=ref('info');
const draft=reactive({itemType:'STORY',priority:'MEDIUM',title:'',description:'',phase:'',startDate:'',dueDate:'',parentId:'',dependsOnId:''});
const selectedTask=ref(null),draggingId=ref(''),timelineScale=ref('month');
const detail=reactive({title:'',description:'',itemType:'TASK',priority:'MEDIUM',phase:'',status:'TODO',startDate:'',dueDate:'',parentId:'',dependsOnId:''});
const dateKey=v=>v?String(v).slice(0,10):'';
const taskName=id=>tasks.value.find(t=>t.id===id)?.title||'Unknown task';
const subtasks=computed(()=>tasks.value.filter(t=>t.parentId===selectedTask.value?.id));
function openDetails(task){if(task.id==='project-charter')return;selectedTask.value=task;error.value='';notice.value='';Object.assign(detail,{title:task.title,description:task.description||'',itemType:task.itemType||'TASK',priority:task.priority||'MEDIUM',phase:task.phase||'',status:task.status,startDate:dateKey(task.startDate),dueDate:dateKey(task.dueDate),parentId:task.parentId||'',dependsOnId:task.dependsOnId||''});}
function dragTask(task,event){if(busy.value)return;draggingId.value=task.id;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',task.id);}
function dropTask(status){const task=tasks.value.find(t=>t.id===draggingId.value);draggingId.value='';if(task&&!busy.value)updateStatus(task,status);}
async function saveDetails(){if(!selectedTask.value)return;error.value='';notice.value='';if(detail.startDate&&detail.dueDate&&detail.dueDate<detail.startDate){error.value='Due date must not precede the start date.';return;}busy.value=true;
try{const original=selectedTask.value;const values={};for(const key of ['title','description','itemType','priority','phase','status','startDate','dueDate','parentId','dependsOnId']){
 const initial=key==='startDate'||key==='dueDate'?dateKey(original[key]):original[key]||'';
 const value=detail[key];if(value===initial)continue;
 if(['startDate','dueDate'].includes(key))values[key]=value?new Date(value+'T12:00:00').toISOString():null;
 else if(['parentId','dependsOnId','phase','description'].includes(key))values[key]=value||null;
 else values[key]=value;
 }
if(!Object.keys(values).length){notice.value='No changes to submit.';return;}
await axios.post('/reviews/operations',{kind:'TASK_UPDATE',projectId:projectId.value,targetId:original.id,summary:'Edit work item '+original.title,values});notice.value='Changes submitted for independent approval.';
}catch(e){error.value=formatError(e);}finally{busy.value=false;}}

const projectId=computed(()=>String(route.params.id||''));
const hours=computed(()=>entries.value.reduce((s,x)=>s+Number(x.hours),0));
const progress=computed(()=>tasks.value.length?Math.round(tasks.value.filter(x=>x.status==='DONE').length/tasks.value.length*100):0);
const phases=computed(()=>[...new Set(tasks.value.map(x=>x.phase||'Unassigned'))]);
const datedItems=computed(()=>[
  ...(project.value&&(project.value.startDate||project.value.targetEndDate)?[{id:'project-charter',title:project.value.name+' · Project plan',status:project.value.status,itemType:'PROJECT',phase:'Overall project',startDate:project.value.startDate,dueDate:project.value.targetEndDate}]:[]),
  ...tasks.value.filter(x=>x.startDate||x.dueDate)
].sort((a,b)=>new Date(a.startDate||a.dueDate)-new Date(b.startDate||b.dueDate)));
const timelineMin=computed(()=>{const min=Math.min(...datedItems.value.map(x=>new Date(x.startDate||x.dueDate).getTime()));const d=new Date(min);if(timelineScale.value==='year')return new Date(d.getFullYear(),0,1).getTime();if(timelineScale.value==='quarter')return new Date(d.getFullYear(),Math.floor(d.getMonth()/3)*3,1).getTime();return new Date(d.getFullYear(),d.getMonth(),1).getTime();});
const timelineMax=computed(()=>{const max=Math.max(...datedItems.value.map(x=>new Date(x.dueDate||x.startDate).getTime()),timelineMin.value+86400000);const d=new Date(max);if(timelineScale.value==='year')return new Date(d.getFullYear()+1,0,1).getTime();if(timelineScale.value==='quarter')return new Date(d.getFullYear(),Math.floor(d.getMonth()/3)*3+3,1).getTime();return new Date(d.getFullYear(),d.getMonth()+1,1).getTime();});
const date=v=>v?new Date(v).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'Not set';
const pretty=v=>v.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,x=>x.toUpperCase());
function barStyle(item){const start=new Date(item.startDate||item.dueDate).getTime(),end=new Date(item.dueDate||item.startDate).getTime(),span=Math.max(86400000,timelineMax.value-timelineMin.value);return {left:Math.max(0,(start-timelineMin.value)/span*100)+'%',width:Math.max(2,Math.min(100,(Math.max(end,start)-start+86400000)/span*100))+'%'};}
const formatError=e=>{const m=e.response?.data?.message;return Array.isArray(m)?m.join(', '):m||e.message||'Operation failed';};
async function load(){loading.value=true;error.value='';try{const id=encodeURIComponent(projectId.value);const [p,t,h]=await Promise.all([axios.get('/projects/'+id),axios.get('/projects/'+id+'/tasks'),axios.get('/projects/'+id+'/timesheets')]);project.value=p.data.data;tasks.value=t.data.data;entries.value=h.data.data;view.value=project.value.deliveryMethod==='WATERFALL'?'waterfall':'info';}catch(e){error.value=formatError(e);}finally{loading.value=false;}}
async function createItem(){error.value='';notice.value='';if(draft.startDate&&draft.dueDate&&draft.dueDate<draft.startDate){error.value='End date must follow start date.';return;}busy.value=true;try{await axios.post('/reviews/operations',{kind:'TASK_CREATE',projectId:projectId.value,summary:'Create '+draft.itemType.toLowerCase()+' '+draft.title,values:{title:draft.title,description:draft.description,itemType:draft.itemType,priority:draft.priority,...(draft.phase?{phase:draft.phase}:{}),...(draft.parentId?{parentId:draft.parentId}:{}),...(draft.dependsOnId?{dependsOnId:draft.dependsOnId}:{}),...(draft.startDate?{startDate:new Date(draft.startDate+'T12:00:00').toISOString()}:{}),...(draft.dueDate?{dueDate:new Date(draft.dueDate+'T12:00:00').toISOString()}: {})}});notice.value='Work item submitted for independent approval.';showCreate.value=false;draft.title='';draft.description='';draft.phase='';draft.startDate='';draft.dueDate='';draft.parentId='';draft.dependsOnId='';}catch(e){error.value=formatError(e);}finally{busy.value=false;}}
async function updateStatus(task,status){error.value='';notice.value='';if(status===task.status)return;busy.value=true;try{await axios.post('/reviews/operations',{kind:'TASK_UPDATE',projectId:projectId.value,targetId:task.id,summary:'Update work item '+task.title,values:{status}});notice.value='Status update submitted for independent approval.';}catch(e){error.value=formatError(e);}finally{busy.value=false;}}
onMounted(load);watch(projectId,load);
</script>
<style scoped>
.hub{padding:29px clamp(16px,3vw,38px);min-height:100vh;background:#f4f7fb;color:#1e2f47}.hub-header{display:flex;align-items:center;justify-content:space-between;gap:15px}.back,.secondary-link{font-size:12px;font-weight:750;color:#315ac4;text-decoration:none}.eyebrow{font-size:10px;color:#4263be;letter-spacing:.12em;font-weight:800;margin-top:20px}.hub-header h1{font-size:30px;margin:7px 0}.hub-header p:not(.eyebrow){font-size:13px;color:#687b97;max-width:740px}.project-pill{border-radius:14px;padding:11px 14px;background:#eaf0ff;color:#315ac4;font-size:11px;font-weight:800}.insights{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin:27px 0}.insights article,.panel{background:white;border:1px solid #e2e9f3;border-radius:15px;padding:23px}.insights article{display:grid;gap:10px}.insights small,.information small{color:#7889a0;font-size:11px}.insights strong{font-size:22px}.hub-tabs{display:flex;gap:7px;overflow-x:auto;border-bottom:1px solid #dae4f1;margin-bottom:17px}.hub-tabs button{white-space:nowrap;border:0;border-bottom:3px solid transparent;background:transparent;color:#63758e;padding:14px 17px;cursor:pointer;font-weight:750;font-size:12px}.hub-tabs button.active{color:#315ac4;border-bottom-color:#315ac4}.section-title{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px;margin-bottom:22px}.section-title h2{font-size:19px;margin:0}.section-title span,.hint{font-size:12px;color:#74839a}.information{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.information>div{background:#f7f9fd;border:1px solid #edf1f8;border-radius:11px;padding:15px;display:grid;gap:9px}.information strong{font-size:13px;overflow-wrap:anywhere}.overview{margin:25px 0}.overview h3{font-size:15px}.overview p{font-size:13px;color:#64748b;white-space:pre-wrap}.primary{border:0;padding:12px 17px;background:#315ac4;color:white;border-radius:9px;font-size:12px;font-weight:750;cursor:pointer}.primary:disabled{opacity:.6}.alert{padding:13px;border-radius:10px;background:#e9f7ee;color:#157450}.alert.error{background:#ffe9ee;color:#a9234b}.scroll-table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}td,th{padding:15px;border-bottom:1px solid #edf1f7}th{color:#74839a;background:#f6f8fc}.empty{font-size:13px;color:#78889d;padding:28px}.item-form{border:1px solid #e2eaf7;background:#f8faff;border-radius:13px;padding:21px;margin-bottom:20px;display:grid;gap:15px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field-grid label{display:grid;gap:7px;font-size:12px;font-weight:750}.field-grid label.wide{grid-column:1/-1}input,textarea{width:100%;border:1px solid #d9e2ef;border-radius:9px;background:#fff;padding:12px;font:inherit;font-size:13px}.backlog,.phases{display:grid;gap:9px}.work-row{display:flex;gap:14px;align-items:center;padding:14px;border:1px solid #e7edf5;border-radius:11px;min-width:0}.work-row>div:nth-child(2){flex:1;min-width:0}.work-row strong,.board-card strong{display:block;font-size:13px;overflow-wrap:anywhere}.work-row small,.board-card small{display:block;margin-top:6px;color:#7989a0;font-size:11px}.work-row .smart-select{flex:0 0 185px;width:185px}.type{font-size:10px;border-radius:6px;padding:7px;background:#eaf0ff;color:#315ac4;font-weight:800}.board{display:grid;grid-template-columns:repeat(4,minmax(190px,1fr));gap:13px;overflow-x:auto}.board-column{background:#f4f7fc;padding:12px;border-radius:13px;min-width:0}.column-head{display:flex;justify-content:space-between;padding:9px 4px 17px;font-size:12px}.column-head span{background:#e1e8f5;border-radius:12px;padding:2px 8px}.board-card{display:grid;gap:9px;margin:0 0 11px;padding:14px;border:1px solid #e4eaf4;border-radius:10px;background:#fff}.task-title{display:block;border:0;background:transparent;color:var(--pmo-text,#1e2f47);text-align:left;font-weight:750;font-size:13px;cursor:pointer;padding:2px 0;overflow-wrap:anywhere}.task-title:hover{text-decoration:underline;color:var(--pmo-accent,#0071e3)}.board-card[draggable=true]{cursor:grab}.board-card[draggable=true]:active{cursor:grabbing}.timeline-controls{display:flex;align-items:center;gap:12px}.timeline-controls .smart-select{width:145px}.timeline-controls label{font-size:12px}.timeline-bar{border:0;cursor:pointer}.timeline-bar:focus-visible{outline:3px solid var(--pmo-accent,#0071e3);outline-offset:2px}.timeline-bar.milestone{min-width:13px!important;width:13px!important;border-radius:3px;transform:rotate(45deg);top:3px;bottom:3px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.task-overlay{position:fixed;z-index:110;inset:0;background:#09111d88;display:grid;place-items:center;padding:18px}.task-dialog{background:var(--pmo-surface,#fff);color:var(--pmo-text,#1e2f47);border-radius:22px;border:1px solid var(--pmo-border,#e4e9f0);width:min(680px,100%);max-height:90vh;display:flex;flex-direction:column;box-shadow:0 30px 90px #08132b50}.task-dialog-head,.task-dialog-actions{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:20px 26px;border-bottom:1px solid var(--pmo-border,#e4e9f0)}.task-dialog-head h2{margin:5px 0 0}.task-dialog-head small{color:var(--pmo-accent,#0071e3)}.icon-close{background:transparent;border:0;color:inherit;cursor:pointer;font-size:18px}.task-dialog-body{padding:20px 26px;overflow-y:auto;display:grid;gap:17px}.task-dialog-body label{display:grid;gap:8px;font-size:12px;font-weight:700}.task-dialog-actions{border-top:1px solid var(--pmo-border,#e4e9f0);border-bottom:0}.task-dialog-actions .secondary{border:1px solid var(--pmo-border,#e4e9f0);border-radius:9px;padding:11px 15px;background:var(--pmo-surface-alt,#f4f5f6);color:var(--pmo-text,#1e2f47);cursor:pointer}.related-items{display:grid;gap:8px}.related-items button{text-align:left;background:var(--pmo-surface-alt,#f6f8fa);border:1px solid var(--pmo-border,#e4e9f0);border-radius:9px;padding:12px;cursor:pointer;color:var(--pmo-text,#1e2f47)}.board-card p{font-size:11px;color:#708098;margin:0;line-height:1.5}.phase{margin:12px 0}.phase h3{font-size:15px}.phase h3 span{font-size:11px;color:#78879e;font-weight:500}.timeline-scroll{min-width:600px;overflow:auto}.timeline-head{display:flex;justify-content:space-between;padding:12px;color:#64748b;font-size:11px;border-bottom:1px solid #e6ebf4}.timeline-row{display:grid;grid-template-columns:200px minmax(240px,1fr) 120px;align-items:center;gap:13px;padding:13px 0;border-bottom:1px solid #edf1f6}.timeline-row strong{font-size:12px}.timeline-row small{font-size:11px;color:#667b99}.timeline-track{background:#eaf0fb;border-radius:15px;height:20px;position:relative}.timeline-bar{position:absolute;top:2px;bottom:2px;background:#6687df;border-radius:8px}.timeline-bar.done{background:#45a68c}.timeline-bar.blocked{background:#e89968}
